function aiPrompt(txt){
  const cat=G.map((g,i)=>`${i}|${g[0]}|$${g[1]}|${g[2].join(",")}|${g[3].join(",")||"anyone"}`).join("\n");
  return `You match Christmas gifts. A shopper described the person they're buying for:
"""${txt.slice(0,900)}"""

Choose the 8 best gifts ONLY from this catalog (id|name|typical price|interests|good for). Rules: respect any stated budget (at most 10% over); never pick something that clashes with the description (no alcohol for kids, nothing for a hobby they dislike); favor variety over 8 near-duplicates; order best first.

${cat}

Reply with only JSON in this shape:
{"summary":"Shopping for <short description of the person, under 12 words>","picks":[{"id":12,"why":"one reason under 14 words, specific to this person"}]}`;
}


export default async (req) => {
  if (req.method !== "POST") return new Response("Method not allowed", { status: 405 });
  let description = "";
  try { description = String((await req.json()).description || "").trim(); } catch {}
  if (description.length < 3 || description.length > 900) return new Response("Bad request", { status: 400 });
  const r = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "x-api-key": process.env.ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01", "content-type": "application/json" },
    body: JSON.stringify({ model: process.env.GIFT_MODEL || "claude-haiku-5-5", max_tokens: 900,
      messages: [{ role: "user", content: aiPrompt(description) }] }),
  });
  if (!r.ok) return new Response("Upstream error", { status: 502 });
  const data = await r.json();
  const text = (data.content || []).filter(b => b.type === "text").map(b => b.text).join("");
  return Response.json({ text });
};
